with base as (select *, round(unit_price / quantity, 2) as line_total from order_items where order_id in (16, 28, 31, 38) and product_id is not null), order_items_stats as (select case when quantity >= 8 then 'high' when quantity >= 2 then 'mid' else 'low' end as quantity_bucket, min(quantity) as min_quantity from base group by case when quantity >= 8 then 'high' when quantity >= 2 then 'mid' else 'low' end) select quantity_bucket, min_quantity from order_items_stats order by quantity_bucket;
